item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [99:0] in,
    output logic out_and,
    output logic out_or,
    output logic out_xor
);
    assign out_and = &in;
    assign out_or  = |in;
    assign out_xor = "'^in;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
module dev_tb;
    logic [99:0] in;
    wire out_and, out_or, out_xor;
    integer checks = 0;
    TopModule dut (.in(in), .out_and(out_and), .out_or(out_or), .out_xor(out_xor));
    task automatic check(input logic [99:0] value);
        logic expected_and, expected_or, expected_xor;
        begin
            expected_and = 1'b1;
            expected_or = 1'b0;
            expected_xor = 1'b0;
            for (integer j = 0; j < 100; j = j + 1) begin
                expected_and = expected_and & value[j];
                expected_or = expected_or | value[j];
                expected_xor = expected_xor "'^ value[j];
            end
            in = value;
            #1;
            if ({out_and, out_or, out_xor} !== {expected_and, expected_or, expected_xor})
                $fatal(1, "FAIL input=%h output=%b%b%b", in, out_and, out_or, out_xor);
            checks = checks + 1;
        end
    endtask
    initial begin
        check(100'"'b0);
        check({100{1'b1}});
        for (integer i = 0; i < 100; i = i + 1) begin
            check(100'b1 << i);
            check(~(100'b1 << i));
        end
        for (integer i = 0; i < 1000; i = i + 1)
            check({"'$urandom, $urandom, $urandom, $urandom});
        check({100{1'"'bx}});
        check({100{1'bz}});
        "'$display("PASS: %0d vectors", checks);
        $finish;
    end
    initial begin
        #10000;
        $fatal(1, "FAIL timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1'

